-- AllFeaturesDb — full create script (dependency-ordered concatenation of all object
-- files, per _apply_order.txt). Generated by hand because `pgproj script` gates on the
-- 2 parse problems documented in README.md; this file applies clean to postgres:18.

-- ===== Schemas/afd.sql =====
CREATE SCHEMA afd;

-- ===== Schemas/reporting.sql =====
CREATE SCHEMA reporting;

-- ===== Extensions/btree_gist.sql =====
-- NOTE: btree_gist ships in the standard postgres:18 contrib set and is required
-- by the EXCLUDE constraint in afd.room_booking (lets a scalar column participate
-- in a GiST exclusion alongside a range).
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ===== Types/afd.mood.sql =====
-- ENUM type
CREATE TYPE afd.mood AS ENUM ('sad', 'ok', 'happy');

-- ===== Types/afd.address.sql =====
-- Composite type
CREATE TYPE afd.address AS (
    street text,
    city   text,
    zip    text
);

-- ===== Types/afd.float_range.sql =====
-- Range type (over a float8 subtype)
CREATE TYPE afd.float_range AS RANGE (SUBTYPE = float8);

-- ===== Types/afd.shell_type.sql =====
-- Shell (placeholder) type declaration. A bare CREATE TYPE with no definition
-- registers a shell type; it would normally be fleshed out into a base type with
-- C-language I/O functions, which this environment cannot compile, so it is left
-- as a shell to exercise the grammar.
CREATE TYPE afd.shell_type;

-- ===== Domains/afd.pos_int.sql =====
-- Domain with a CHECK constraint and NOT NULL
CREATE DOMAIN afd.pos_int AS integer
    NOT NULL
    CHECK (VALUE > 0);

-- ===== Domains/afd.email.sql =====
-- Domain over text with a named CHECK constraint and a DEFAULT
CREATE DOMAIN afd.email AS text
    DEFAULT 'unknown@example.com'
    CONSTRAINT email_format CHECK (VALUE ~ '^[^@]+@[^@]+\.[^@]+$');

-- ===== Collations/afd.case_insensitive.sql =====
-- ICU collation: case-insensitive, deterministic=false (PG12+; ICU ships with pg18).
CREATE COLLATION afd.case_insensitive (
    PROVIDER      = icu,
    LOCALE        = 'und-u-ks-level2',
    DETERMINISTIC = false
);

-- ===== Conversions/afd.latin1_to_utf8.sql =====
-- Conversion built on a built-in conversion function.
CREATE CONVERSION afd.latin1_to_utf8 FOR 'LATIN1' TO 'UTF8' FROM iso8859_1_to_utf8;

-- ===== Sequences/afd.order_no_seq.sql =====
-- Standalone sequence exercising the full option list.
CREATE SEQUENCE afd.order_no_seq
    AS bigint
    INCREMENT BY 10
    MINVALUE 1000
    MAXVALUE 9999999999
    START WITH 1000
    CACHE 5
    CYCLE;

-- ===== Tables/afd.customers.sql =====
-- Flagship table: every common column type, generation strategy and inline constraint.
CREATE TABLE afd.customers (
    -- identity (BY DEFAULT) + composite PK with INCLUDE (see table constraint below)
    id              bigint        GENERATED BY DEFAULT AS IDENTITY,
    tenant_id       integer       NOT NULL DEFAULT 1,

    -- text / character types, one using the custom collation + domain
    email           afd.email     NOT NULL,
    full_name       text          NOT NULL,
    code            char(8),
    short_name      varchar(50)   COLLATE afd.case_insensitive,
    notes           text,

    -- numeric family
    balance_cents   bigint        NOT NULL DEFAULT 0,
    score           numeric(10,2) NOT NULL DEFAULT 0,
    rating          real,
    big_rating      double precision,
    qty             afd.pos_int   DEFAULT 1,
    serial_no       serial,
    big_serial_no   bigserial,

    -- boolean / temporal
    is_active       boolean       NOT NULL DEFAULT true,
    created_at      timestamptz   NOT NULL DEFAULT now(),
    born_on         date,
    wake_time       time,
    duration        interval,

    -- network / bit / uuid / money
    ip_addr         inet,
    mac             macaddr,
    flags           bit(8),
    varflags        bit varying(16),
    ext_id          uuid          DEFAULT gen_random_uuid(),
    wallet          money,

    -- arrays
    tags            text[]        NOT NULL DEFAULT '{}',
    scores          integer[],
    matrix          numeric(6,2)[][],

    -- json / xml
    profile         jsonb         NOT NULL DEFAULT '{}'::jsonb,
    legacy_doc      json,
    xml_doc         xml,

    -- composite / enum / domain / range types
    home            afd.address,
    status          afd.mood      NOT NULL DEFAULT 'ok',
    valid_period    tstzrange,
    temp_range      afd.float_range,

    -- geometric (for the EXCLUDE example elsewhere) + tsvector
    region          circle,
    search          tsvector,

    -- DEFAULT drawing from a sequence
    order_no        bigint        NOT NULL DEFAULT nextval('afd.order_no_seq'),

    -- GENERATED ALWAYS AS STORED (computed column)
    name_upper      text          GENERATED ALWAYS AS (upper(full_name)) STORED,
    balance_dollars numeric(20,2) GENERATED ALWAYS AS (balance_cents / 100.0) STORED,

    -- inline column constraints
    discount        integer       CHECK (discount BETWEEN 0 AND 100),
    referral_email  afd.email     UNIQUE NULLS NOT DISTINCT,

    -- composite primary key with an INCLUDE (non-key) column
    CONSTRAINT customers_pk PRIMARY KEY (tenant_id, id) INCLUDE (email),

    -- named table-level CHECK
    CONSTRAINT customers_score_chk CHECK (score >= 0),

    -- table-level UNIQUE with INCLUDE
    CONSTRAINT customers_email_uq UNIQUE (tenant_id, email) INCLUDE (full_name)
);

-- ===== Tables/afd.orders.sql =====
-- FK with composite reference, explicit ON DELETE/UPDATE actions, MATCH and DEFERRABLE.
CREATE TABLE afd.orders (
    id            bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id     integer     NOT NULL,
    customer_id   bigint      NOT NULL,
    total_cents   integer     NOT NULL DEFAULT 0 CHECK (total_cents >= 0),
    placed_at     timestamptz NOT NULL DEFAULT now(),

    -- composite FK with full action/match/deferrable surface
    CONSTRAINT orders_customer_fk
        FOREIGN KEY (tenant_id, customer_id)
        REFERENCES afd.customers (tenant_id, id)
        MATCH SIMPLE
        ON DELETE CASCADE
        ON UPDATE RESTRICT
        DEFERRABLE INITIALLY DEFERRED
);

-- ===== Tables/afd.room_booking.sql =====
-- EXCLUDE constraint: no two bookings of the same room may overlap in time.
-- Requires btree_gist so the scalar room_id can sit in a GiST index next to the range.
CREATE TABLE afd.room_booking (
    id        bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    room_id   integer     NOT NULL,
    during    tstzrange   NOT NULL,
    CONSTRAINT room_no_overlap
        EXCLUDE USING gist (room_id WITH =, during WITH &&)
);

-- ===== Tables/afd.events.sql =====
-- RANGE-partitioned table. The partition key must be part of the PK.
CREATE TABLE afd.events (
    id        bigint GENERATED BY DEFAULT AS IDENTITY,
    occurred  date   NOT NULL,
    kind      text   NOT NULL,
    payload   jsonb,
    PRIMARY KEY (id, occurred)
) PARTITION BY RANGE (occurred);

-- ===== Tables/afd.events_2024.sql =====
-- A concrete partition of afd.events for the 2024 calendar year.
CREATE TABLE afd.events_2024 PARTITION OF afd.events
    FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');

-- ===== Tables/afd.events_default.sql =====
-- DEFAULT partition catches rows outside every explicit range.
CREATE TABLE afd.events_default PARTITION OF afd.events DEFAULT;

-- ===== Tables/afd.base_entity.sql =====
-- Parent table for an INHERITS relationship.
CREATE TABLE afd.base_entity (
    id         bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT now(),
    kind       text        NOT NULL
);

-- ===== Tables/afd.document.sql =====
-- INHERITS table: adds its own columns on top of afd.base_entity's.
CREATE TABLE afd.document (
    title text NOT NULL,
    body  text
) INHERITS (afd.base_entity);

-- ===== Tables/afd.address_row.sql =====
-- Table OF a composite type: columns come from afd.address.
CREATE TABLE afd.address_row OF afd.address (
    PRIMARY KEY (zip)
);

-- ===== Tables/afd.customers_archive.sql =====
-- LIKE clause: copy column definitions, defaults and constraints from afd.customers.
CREATE TABLE afd.customers_archive (
    archived_at timestamptz NOT NULL DEFAULT now(),
    LIKE afd.customers INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING COMMENTS
);

-- ===== Indexes/afd.customers_email_idx.sql =====
-- Plain unique btree index.
CREATE UNIQUE INDEX customers_email_idx ON afd.customers (tenant_id, email);

-- ===== Indexes/afd.customers_active_idx.sql =====
-- Partial index (WHERE predicate) with an INCLUDE payload column.
CREATE INDEX customers_active_idx
    ON afd.customers (full_name)
    INCLUDE (email)
    WHERE is_active;

-- ===== Indexes/afd.customers_name_lower_idx.sql =====
-- Expression index with an explicit btree opclass and ordering options.
CREATE INDEX customers_name_lower_idx
    ON afd.customers USING btree (lower(full_name) text_pattern_ops ASC NULLS LAST);

-- ===== Indexes/afd.customers_profile_gin.sql =====
-- GIN index over a jsonb column with an explicit opclass.
CREATE INDEX customers_profile_gin
    ON afd.customers USING gin (profile jsonb_path_ops);

-- ===== Indexes/afd.customers_region_gist.sql =====
-- GiST index over a geometric column.
CREATE INDEX customers_region_gist
    ON afd.customers USING gist (region);

-- ===== Indexes/afd.customers_tags_gin.sql =====
-- GIN index over an array column with a storage parameter.
CREATE INDEX customers_tags_gin
    ON afd.customers USING gin (tags) WITH (fastupdate = on);

-- ===== Functions/afd.add.sql =====
-- SQL function: scalar return, IMMUTABLE/STRICT/PARALLEL SAFE, arg default.
CREATE FUNCTION afd.add(a integer, b integer DEFAULT 0)
    RETURNS integer
    LANGUAGE sql
    IMMUTABLE
    STRICT
    PARALLEL SAFE
    RETURN a + b;

-- ===== Functions/afd.split_name.sql =====
-- SQL function with OUT parameters (implicit composite return).
CREATE FUNCTION afd.split_name(
    IN  full_name text,
    OUT first_name text,
    OUT last_name  text
)
    LANGUAGE sql
    IMMUTABLE
AS $$
    SELECT split_part(full_name, ' ', 1),
           split_part(full_name, ' ', 2)
$$;

-- ===== Functions/afd.accumulate.sql =====
-- VARIADIC argument + INOUT, exercised via a plpgsql body.
CREATE FUNCTION afd.accumulate(INOUT running bigint, VARIADIC vals integer[])
    LANGUAGE plpgsql
    IMMUTABLE
AS $$
DECLARE
    v integer;
BEGIN
    FOREACH v IN ARRAY vals LOOP
        running := running + v;
    END LOOP;
END;
$$;

-- ===== Functions/afd.active_customers.sql =====
-- SETOF return over a table type.
CREATE FUNCTION afd.active_customers()
    RETURNS SETOF afd.customers
    LANGUAGE sql
    STABLE
    SECURITY DEFINER
AS $$
    SELECT * FROM afd.customers WHERE is_active
$$;

-- ===== Functions/afd.customer_stats.sql =====
-- RETURNS TABLE (named columns) implemented in PL/pgSQL with a RETURN QUERY.
CREATE FUNCTION afd.customer_stats(min_score numeric DEFAULT 0)
    RETURNS TABLE (status afd.mood, customer_count bigint, avg_score numeric)
    LANGUAGE plpgsql
    STABLE
AS $$
BEGIN
    RETURN QUERY
        SELECT c.status, count(*), avg(c.score)
        FROM afd.customers c
        WHERE c.score >= min_score
        GROUP BY c.status;
END;
$$;

-- ===== Functions/afd.touch_updated_at.sql =====
-- Trigger function (row-level): used by afd.customers_touch.
CREATE FUNCTION afd.touch_updated_at()
    RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    NEW.created_at := now();
    RETURN NEW;
END;
$$;

-- ===== Functions/afd.log_ddl.sql =====
-- Event-trigger function (RETURNS event_trigger): used by the audit_ddl event trigger.
CREATE FUNCTION afd.log_ddl()
    RETURNS event_trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    RAISE NOTICE 'DDL command % executed', tg_tag;
END;
$$;

-- ===== Functions/afd.mood_to_int.sql =====
-- Conversion function backing the afd.mood -> integer cast.
CREATE FUNCTION afd.mood_to_int(m afd.mood)
    RETURNS integer
    LANGUAGE sql
    IMMUTABLE
    STRICT
AS $$
    SELECT CASE m WHEN 'sad' THEN -1 WHEN 'ok' THEN 0 WHEN 'happy' THEN 1 END
$$;

-- ===== Functions/afd.mood_eq.sql =====
-- Equality function backing the custom === operator on afd.mood.
CREATE FUNCTION afd.mood_eq(a afd.mood, b afd.mood)
    RETURNS boolean
    LANGUAGE sql
    IMMUTABLE
    STRICT
AS $$
    SELECT a = b
$$;

-- ===== Procedures/afd.archive_customer.sql =====
-- Stored procedure with IN/INOUT args and a transaction-free body. Procedures may
-- COMMIT; here we just move a row and report the archived id back via INOUT.
CREATE PROCEDURE afd.archive_customer(IN p_tenant integer, IN p_id bigint, INOUT moved boolean DEFAULT false)
    LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO afd.customers_archive
    SELECT now(), c.*
    FROM afd.customers c
    WHERE c.tenant_id = p_tenant AND c.id = p_id;

    DELETE FROM afd.customers c
    WHERE c.tenant_id = p_tenant AND c.id = p_id;

    moved := FOUND;
END;
$$;

-- ===== Aggregates/afd.sum_int.sql =====
-- User-defined aggregate built on the built-in int4pl transition function.
CREATE AGGREGATE afd.sum_int (integer) (
    SFUNC    = int4pl,
    STYPE    = integer,
    INITCOND = '0'
);

-- ===== Casts/afd.mood_as_int.sql =====
-- Cast from the enum to integer using a SQL function, available on assignment.
CREATE CAST (afd.mood AS integer) WITH FUNCTION afd.mood_to_int(afd.mood) AS ASSIGNMENT;

-- ===== Operators/afd.mood_eq_op.sql =====
-- Custom binary operator with commutator and a selectivity estimator.
CREATE OPERATOR afd.=== (
    FUNCTION   = afd.mood_eq,
    LEFTARG    = afd.mood,
    RIGHTARG   = afd.mood,
    COMMUTATOR = OPERATOR(afd.===),
    HASHES,
    MERGES
);

-- ===== OperatorClasses/afd.int_minmax_ops.sql =====
-- Operator class for integer under btree built from existing operators/support fn.
CREATE OPERATOR CLASS afd.int_minmax_ops
    FOR TYPE integer USING btree AS
        OPERATOR 1 <,
        OPERATOR 2 <=,
        OPERATOR 3 =,
        OPERATOR 4 >=,
        OPERATOR 5 >,
        FUNCTION 1 btint4cmp(integer, integer);

-- ===== TextSearch/afd.english_dict.sql =====
-- Text-search dictionary built from the built-in simple template.
CREATE TEXT SEARCH DICTIONARY afd.english_dict (
    TEMPLATE  = pg_catalog.simple,
    STOPWORDS = english
);

-- ===== TextSearch/afd.english_cfg.sql =====
-- Text-search configuration copied from the built-in english config, then remapped
-- to use our dictionary for word tokens.
CREATE TEXT SEARCH CONFIGURATION afd.english_cfg (COPY = pg_catalog.english);

ALTER TEXT SEARCH CONFIGURATION afd.english_cfg
    ALTER MAPPING FOR asciiword, word WITH afd.english_dict;

-- ===== Views/afd.customer_orders.sql =====
-- Aggregating view joining customers and orders.
CREATE VIEW afd.customer_orders AS
SELECT c.tenant_id,
       c.id                              AS customer_id,
       c.email,
       count(o.id)                       AS order_count,
       coalesce(sum(o.total_cents), 0)   AS total_cents
FROM afd.customers c
LEFT JOIN afd.orders o
       ON o.tenant_id = c.tenant_id AND o.customer_id = c.id
GROUP BY c.tenant_id, c.id, c.email;

-- ===== Views/afd.active_customers_v.sql =====
-- Updatable view with WITH CASCADED CHECK OPTION: inserts/updates that violate
-- the WHERE predicate are rejected.
CREATE VIEW afd.active_customers_v AS
SELECT tenant_id, id, email, full_name, is_active, status
FROM afd.customers
WHERE is_active
WITH CASCADED CHECK OPTION;

-- ===== Views/reporting.customer_mv.sql =====
-- Materialized view in the reporting schema (built WITH DATA).
CREATE MATERIALIZED VIEW reporting.customer_mv AS
SELECT status, count(*) AS n, avg(score) AS avg_score
FROM afd.customers
GROUP BY status
WITH DATA;

-- ===== Triggers/afd.customers_touch.sql =====
-- Row-level BEFORE UPDATE trigger with a WHEN condition.
CREATE TRIGGER customers_touch
    BEFORE UPDATE ON afd.customers
    FOR EACH ROW
    WHEN (OLD.full_name IS DISTINCT FROM NEW.full_name)
    EXECUTE FUNCTION afd.touch_updated_at();

-- ===== Triggers/afd.orders_stmt_audit.sql =====
-- Statement-level AFTER trigger covering multiple events.
CREATE TRIGGER orders_stmt_audit
    AFTER INSERT OR UPDATE OR DELETE ON afd.orders
    FOR EACH STATEMENT
    EXECUTE FUNCTION afd.touch_updated_at();

-- ===== EventTriggers/afd.audit_ddl.sql =====
-- Event trigger on ddl_command_end, filtered to a set of command tags.
CREATE EVENT TRIGGER audit_ddl
    ON ddl_command_end
    WHEN TAG IN ('CREATE TABLE', 'ALTER TABLE', 'DROP TABLE')
    EXECUTE FUNCTION afd.log_ddl();

-- ===== Rules/afd.orders_no_delete.sql =====
-- Rule that turns DELETEs on orders into no-ops (DO INSTEAD NOTHING).
CREATE RULE orders_no_delete AS
    ON DELETE TO afd.orders
    DO INSTEAD NOTHING;

-- ===== Policies/afd.customers_rls.sql =====
-- Row-level security: enable RLS, then a permissive per-tenant policy.
ALTER TABLE afd.customers ENABLE ROW LEVEL SECURITY;

CREATE POLICY customers_tenant_isolation ON afd.customers
    AS PERMISSIVE
    FOR ALL
    TO PUBLIC
    USING (tenant_id = current_setting('afd.tenant_id', true)::integer)
    WITH CHECK (tenant_id = current_setting('afd.tenant_id', true)::integer);

-- ===== ForeignDataWrappers/afd.dummy_fdw.sql =====
-- Handler-less foreign data wrapper so it applies without a contrib .so.
CREATE FOREIGN DATA WRAPPER dummy_fdw NO HANDLER NO VALIDATOR OPTIONS (debug 'true');

-- ===== ForeignServers/afd.dummy_server.sql =====
-- Foreign server over the handler-less FDW.
CREATE SERVER dummy_server
    FOREIGN DATA WRAPPER dummy_fdw
    OPTIONS (host 'localhost', dbname 'remote');

-- ===== ForeignTables/afd.remote_customers.sql =====
-- Foreign table on the dummy server. It cannot be queried (no handler) but the
-- definition is valid DDL and applies cleanly.
CREATE FOREIGN TABLE afd.remote_customers (
    id    bigint NOT NULL,
    email text
)
    SERVER dummy_server
    OPTIONS (schema_name 'public', table_name 'customers');

-- ===== Publications/afd.customer_pub.sql =====
-- Logical-replication publication over two tables with a publish parameter.
CREATE PUBLICATION customer_pub
    FOR TABLE afd.customers, afd.orders
    WITH (publish = 'insert, update');

-- ===== Statistics/afd.customers_stats.sql =====
-- Extended statistics object over correlated columns.
CREATE STATISTICS afd.customers_stats (ndistinct, dependencies, mcv)
    ON tenant_id, status, is_active
    FROM afd.customers;

-- ===== Comments/afd.comments.sql =====
-- COMMENT ON a spread of object kinds.
COMMENT ON SCHEMA afd IS 'All-features showcase schema';
COMMENT ON TABLE afd.customers IS 'Customer master records (flagship table)';
COMMENT ON COLUMN afd.customers.profile IS 'Arbitrary JSONB customer profile';
COMMENT ON VIEW afd.customer_orders IS 'Per-customer order rollup';
COMMENT ON MATERIALIZED VIEW reporting.customer_mv IS 'Cached customer counts by status';
COMMENT ON FUNCTION afd.add(integer, integer) IS 'Add two integers';
COMMENT ON TYPE afd.mood IS 'Three-valued mood enum';
COMMENT ON DOMAIN afd.email IS 'Validated email address';
COMMENT ON INDEX afd.customers_email_idx IS 'Unique email per tenant';
COMMENT ON SEQUENCE afd.order_no_seq IS 'Human-facing order numbers';
COMMENT ON TRIGGER customers_touch ON afd.customers IS 'Bumps created_at on rename';


